import React from 'react';
import { render, screen } from '@testing-library/react';
import { Breadcrumb } from '../..';

const { Root, HomeItem, Item } = Breadcrumb;

describe('Breadcrumb', () => {
  it('should render homeItem with asChild and the items', () => {
    render(
      <Root>
        <HomeItem asChild>
          <a href="/">Home</a>
        </HomeItem>
        <Item asChild>
          <a href="/">Page Name 1</a>
        </Item>
        <Item href="/">Page Name 2</Item>
        <Item isCurrentPage>Current Page</Item>
      </Root>
    );
    expect(screen.getByTestId('Home')).toBeInTheDocument();
    expect(screen.getByText('Page Name 1')).toBeInTheDocument();
    expect(screen.getByText('Page Name 2')).toBeInTheDocument();
    expect(screen.getByText('Current Page')).toBeInTheDocument();
  });

  it('should render default homeItem and the items', () => {
    render(
      <Root>
        <HomeItem href="/" />
        <Item asChild>
          <a href="/">Page Name 1</a>
        </Item>
        <Item href="/">Page Name 2</Item>
        <Item isCurrentPage>Current Page</Item>
      </Root>
    );
    expect(screen.getByTestId('Home')).toBeInTheDocument();
    expect(screen.getByText('Page Name 1')).toBeInTheDocument();
    expect(screen.getByText('Page Name 2')).toBeInTheDocument();
    expect(screen.getByText('Current Page')).toBeInTheDocument();
  });
});
